cat > docs/features/checkout-pricing/discount.feature <<'EOF'
# Settled: Bronze, Silver and Gold reductions (AC-1 to AC-4).
# NOT settled: the Platinum tier. The business has not agreed a reduction, so no scenario
# exists for it. Do not add one until an expected value is agreed.
@discount
Feature: Loyalty tier reduction at checkout

  @happy-path
  Scenario: Bronze returning customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver returning customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold returning customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze returning customer with a small basket is charged a whole number of cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/Discount/DiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    [Fact]
    public void Bronze_returning_customer_is_charged_the_Bronze_price()
    {
        // Bronze returning customer is charged the Bronze price
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
cat > src/CheckoutPricing.Application/CalculateLoyaltyDiscount.cs <<'EOF'
